export type InboxPagesProps = {path: string; navigate: (path: string) => void; authenticated: boolean; payables: Payable[]; config?: Config; onLogin: () => void; onDemoLogin?: () => void; onNotice: (message: string) => void; search?: string; cases?: CaseDTO[]; embedded?: boolean};
export type Example = {id: string; title: string; channel: InboxChannel; text: string; payableId?: string; sender?: string};
export type InboxDetailProps = Pick<InboxPagesProps,'authenticated'|'navigate'|'onLogin'|'onNotice'|'embedded'> & {id:string;paymentEmbedded?:boolean};
export type NotificationsProps = Pick<InboxPagesProps,'authenticated'|'navigate'|'onLogin'|'onNotice'|'embedded'>;
export type IntakeDialogProps = {channel:InboxChannel|null;onChannelChange:(channel:InboxChannel)=>void;onClose:()=>void;payables:Payable[];example?:Example;onNotice:(message:string)=>void;onComplete:(id:string)=>void;onBatch?:(ids:string[],options?:{keepOpen?:boolean})=>void};
const sourceIcons = {invoice: FileText, email: Mail, voice: AudioLines, text: MessageSquare};
const stageIcons: Record<string, typeof Shield> = {classification: Inbox, security: ShieldCheck, client_finance: UserRound, policy: ClipboardCheck, final_audit: CheckCheck};
async function downloadNextTestInvoice() {
  const response = await fetch('/api/v1/inbox/test-invoice.pdf', {credentials: 'same-origin'});
  if (!response.ok) {
    const error = (response.headers.get('content-type') || '').includes('json') ? await response.json() : {};
    throw new Error(error.message || error.error?.message || 'The test invoice could not be downloaded. Please try again.');
  }
  const blob = await response.blob();
  if (!blob.type.toLowerCase().includes('application/pdf') || blob.size > 10 * 1024 * 1024 || await blob.slice(0,5).text() !== '%PDF-') throw new Error('The server did not return a readable PDF invoice. Please try again.');
  const disposition = response.headers.get('content-disposition') || '';
  const filename = (/filename="?([^";]+)"?/i.exec(disposition)?.[1] || 'next-10-DEMO-test-invoice.pdf').replace(/[^a-zA-Z0-9._-]+/g, '-');
  const url = URL.createObjectURL(blob), anchor = document.createElement('a');
  anchor.href = url; anchor.download = filename;
  document.body.appendChild(anchor); anchor.click(); anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 60000);
  return filename;
}
function publicText(value: string) {return value.replace(/0x[a-fA-F0-9]{8,64}/g, '[technical reference]');}
function time(value?: string) {if (!value) return 'Just received'; const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Received' : new Intl.DateTimeFormat('en', {month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'}).format(date);}
function ErrorState({error, retry}: {error: unknown; retry: () => void}) {return <div className="sf-state-card sf-error-state" role="alert"><span className="sf-state-icon"><RefreshCw size={27}/></span><h2>We couldn't load your workspace</h2><p>{error instanceof Error ? error.message : 'The server is not responding. Your saved items have not been changed.'}</p><button className="sf-btn sf-btn-primary" onClick={retry}><RefreshCw size={16}/>Try again</button></div>;}
function StatusPill({status}: {status: string}) {return <span className={`sf-pill sf-status-${status}`}>{status === 'approved' ? <Check size={12}/> : status === 'quarantined' ? <ShieldAlert size={12}/> : status === 'processing' ? <LoaderCircle className="sf-spin" size={12}/> : <span/>}{statusNames[status as keyof typeof statusNames] || readable(status)}</span>;}
function SourceIcon({channel, small = false}: {channel: InboxChannel; small?: boolean}) {const Icon = sourceIcons[channel] || FileText;return <span className={`sf-source-icon sf-channel-${channel} ${small ? 'sf-source-small' : ''}`}><Icon size={small ? 17 : 21}/></span>;}
function PageHeading({eyebrow, title, description, children}: {eyebrow?: string; title: string; description: string; children?: ReactNode}) {return <div className="sf-page-heading"><div>{eyebrow && <p className="sf-eyebrow">{eyebrow}</p>}<h1>{title}<span className="sf-heading-dot">.</span></h1><p>{description}</p></div>{children}</div>;}
function Evidence({value}: {value: unknown}) {if (!Array.isArray(value) || !value.length) return null;return <div className="sf-evidence-list">{value.map((entry, index) => {const e = typeof entry === 'string' ? {label: entry} : entry as {label?: string;quote?: string;reference?: string;kind?: string};return <div key={index}><span className="sf-evidence-mark"><FileText size={14}/></span><div><strong>{publicText(e.label || 'Recorded observation')}</strong>{e.quote && <blockquote>{publicText(e.quote)}</blockquote>}{e.reference && <small>{publicText(e.reference)}</small>}</div></div>;})}</div>;}

export function useInbox(authenticated: boolean) {return useQuery({queryKey: ['inbox'], queryFn: () => request<InboxList>('/inbox?limit=100'), enabled: authenticated, refetchInterval: 7000, retry: 1});}

export function InboxPages(props: InboxPagesProps) {
  const {path, authenticated, navigate, config, onNotice} = props;
  const inbox = useInbox(authenticated);
  const queryClient = useQueryClient();
  const [intake, setIntake] = useState<InboxChannel | null>(null);
  const [example, setExample] = useState<Example | undefined>();
  const [walkthrough, setWalkthrough] = useState(false);
  const detailId = path.startsWith('/inbox/') ? path.split('/')[2] : undefined;
  const composeAuthRequested = useRef(false);
  useEffect(() => {
    const openRequestedSource = () => {
      const url = new URL(window.location.href);
      const requested = url.searchParams.get('new');
      if (!requested || !['invoice','email','voice','text'].includes(requested)) {composeAuthRequested.current = false; return;}
      if (!authenticated) {
        if (!config || composeAuthRequested.current) return;
        composeAuthRequested.current = true;
        if (config.demoLoginAvailable && props.onDemoLogin) props.onDemoLogin(); else props.onLogin();
        return;
      }
      setExample(undefined); setIntake(requested as InboxChannel); composeAuthRequested.current = false;
      url.searchParams.delete('new');
      window.history.replaceState(window.history.state, '', url.pathname + url.search + url.hash);
    };
    openRequestedSource();
    window.addEventListener('sf:navigate', openRequestedSource);
    window.addEventListener('popstate', openRequestedSource);
    return () => {window.removeEventListener('sf:navigate', openRequestedSource); window.removeEventListener('popstate', openRequestedSource);};
  }, [authenticated, path, config, props.onDemoLogin, props.onLogin]);
  const openIntake = (channel: InboxChannel, sample?: Example) => {if (!authenticated) {navigate(`/?new=${channel}`);return;}setExample(sample);setIntake(channel);};
  return <>
    {path === '/connections' ? <Connections {...props} onIntake={openIntake}/> : path === '/notifications' ? <Notifications {...props}/> : detailId ? <InboxDetail {...props} id={detailId}/> : <InboxHome {...props} items={inbox.data?.items || []} total={inbox.data?.total || 0} loading={inbox.isLoading && authenticated} error={inbox.error} retry={() => void inbox.refetch()} onIntake={openIntake} onWalkthrough={() => setWalkthrough(!walkthrough)} walkthrough={walkthrough}/>}
    <IntakeDialog channel={intake} onChannelChange={setIntake} onClose={() => {setIntake(null);setExample(undefined);}} payables={props.payables} example={example} onNotice={onNotice} onComplete={id => {setIntake(null);setExample(undefined);void queryClient.invalidateQueries({queryKey: ['inbox']});void queryClient.invalidateQueries({queryKey: ['inbox-notifications']});void queryClient.invalidateQueries({queryKey: ['cases']});navigate(`/inbox/${id}`);}}/>
  </>;
}

function InboxHome({items, total, loading, error, retry, onIntake, onWalkthrough, walkthrough, ...props}: InboxPagesProps & {items: InboxItem[];total: number;loading: boolean;error: unknown;retry: () => void;onIntake: (channel: InboxChannel, sample?: Example) => void;onWalkthrough: () => void;walkthrough: boolean}) {
  const readFilter = () => {
    const requested = new URLSearchParams(window.location.search).get('filter');
    return requested && ['review', 'blocked', 'approved'].includes(requested) ? requested : 'all';
  };
  const [filter, setFilter] = useState(readFilter);
  const [channel, setChannel] = useState('all');
  useEffect(() => {
    const syncFilter = () => setFilter(readFilter());
    syncFilter();
    window.addEventListener('sf:navigate', syncFilter);
    window.addEventListener('popstate', syncFilter);
    return () => {window.removeEventListener('sf:navigate', syncFilter); window.removeEventListener('popstate', syncFilter);};
  }, [props.path]);
  const selectFilter = (value: string) => {
    const url = new URL(window.location.href);
    if (value === 'all') url.searchParams.delete('filter'); else url.searchParams.set('filter', value);
    props.navigate(url.pathname + url.search + url.hash);
  };
  const visible = items.filter(item => (filter === 'all' || filter === 'review' && ['needs_review','quarantined'].includes(item.status) || filter === 'approved' && item.status === 'approved' || filter === 'blocked' && item.status === 'quarantined') && (channel === 'all' || item.channel === channel) && `${item.title} ${item.sender} ${item.preview}`.toLowerCase().includes((props.search || '').trim().toLowerCase()));
  const review = items.filter(item => ['needs_review','quarantined'].includes(item.status));
  const blocked = items.filter(item => item.status === 'quarantined');
  const approved = items.filter(item => item.status === 'approved');
  const examples = useQuery({queryKey: ['inbox-demo-examples'], queryFn: () => request<{examples: Example[];disclaimer: string}>('/inbox/demo-examples'), enabled: props.authenticated && props.config?.appEnv === 'local', retry: false});
  const sources: InboxChannel[] = ['invoice','email','voice','text'];
  const counts = {all: total, review: review.length, blocked: blocked.length, approved: approved.length};
  return <main className="sf-page sf-inbox-page sf-inbox-compact">
    <header className="sf-inbox-heading"><div><h1>Inbox</h1><p>Add a source, then review what needs your attention.</p></div><button className="sf-btn sf-btn-primary" onClick={() => onIntake('invoice')}><Plus size={17}/>Add to inbox</button></header>
    <section className="sf-card sf-inbox-list">
      <div className="sf-list-toolbar sf-compact-toolbar">
        <div className="sf-tabs" aria-label="Filter inbox">{([['all','All items'],['review','Needs review'],['blocked','Security holds'],['approved','Approved']] as const).map(([id,name]) => <button key={id} className={filter === id ? 'is-active' : ''} aria-pressed={filter === id} onClick={() => selectFilter(id)}>{name}{props.authenticated && !loading && !error && <span className="sf-filter-count">{counts[id]}</span>}</button>)}</div>
        {props.authenticated && <label className="sf-channel-filter"><Filter size={14}/><select aria-label="Filter by source" value={channel} onChange={e => setChannel(e.target.value)}><option value="all">All sources</option>{sources.map(source => <option key={source} value={source}>{channelNames[source]}</option>)}</select><ChevronDown size={12}/></label>}
        <button className="sf-icon-btn" aria-label="Refresh inbox" onClick={retry} disabled={!props.authenticated}><RefreshCw size={16}/></button>
      </div>
      {!props.authenticated ? <div className="sf-welcome-state"><span className="sf-state-icon"><Inbox size={30}/></span><h2>Sign in to see your inbox</h2><p>Keep invoices, emails and requests together, with a record of each decision.</p><button className="sf-btn sf-btn-primary" onClick={props.config?.demoLoginAvailable && props.onDemoLogin ? props.onDemoLogin : props.onLogin}>{props.config?.demoLoginAvailable ? 'Explore the demo' : 'Sign in to your workspace'}<ArrowRight size={16}/></button><span className="sf-fine-print">{props.config?.demoLoginAvailable ? 'Local demo with synthetic data.' : 'Use an authorized account to view your items.'}</span></div> : error ? <ErrorState error={error} retry={retry}/> : loading ? <div className="sf-state-card"><LoaderCircle className="sf-spin" size={25}/><p>Loading your inbox…</p></div> : visible.length ? <div className="sf-inbox-rows">{visible.map(item => <button className="sf-inbox-row" data-testid={`inbox-row-${item.id}`} key={item.id} onClick={() => props.navigate(`/inbox/${item.id}`)}><SourceIcon channel={item.channel}/><div className="sf-row-copy"><div className="sf-row-title"><h3>{item.title}</h3><time>{time(item.createdAt)}</time></div><p>{publicText(item.preview)}</p><div className="sf-row-meta"><span>{item.sender || `${channelNames[item.channel]} import`}</span>{item.risks.filter(r => r.severity !== 'info').length > 0 && <span className="sf-risk-count"><ShieldAlert size={12}/>{item.risks.filter(r => r.severity !== 'info').length} security signals</span>}</div></div><div className="sf-row-end"><StatusPill status={item.status}/>{item.payment?.settlementStatus==='SETTLED'&&<span className="sf-pill sf-status-approved"><CheckCheck size={12}/>Payment verified</span>}<ChevronRight size={17}/></div></button>)}</div> : <div className="sf-state-card"><span className="sf-state-icon"><Inbox size={30}/></span><h2>{!items.length ? 'Your inbox is empty' : 'No matching items'}</h2><p>{!items.length ? 'Use Add to inbox to upload an invoice, email or voice file, or paste a request.' : 'Try another filter or search term.'}</p></div>}
      {props.authenticated && !loading && !error && <footer className="sf-list-footer"><span>{visible.length} {visible.length === 1 ? 'item' : 'items'} shown{total > items.length ? ` · Filters cover the latest ${items.length} of ${total} items` : ''}</span></footer>}
    </section>
    {props.config?.appEnv === 'local' && <div className="sf-demo-disclosure"><button className="sf-text-btn" aria-expanded={walkthrough} aria-controls="inbox-demo-examples" onClick={onWalkthrough}>Demo walkthrough <ChevronDown size={14}/></button>{walkthrough && <section id="inbox-demo-examples" className="sf-card sf-walkthrough"><div className="sf-section-heading"><div><h2>Try a synthetic example</h2><p>Choose an example, then add it for review.</p></div></div>{!props.authenticated ? <button className="sf-btn sf-btn-secondary" onClick={props.config?.demoLoginAvailable && props.onDemoLogin ? props.onDemoLogin : props.onLogin}>Enter the demo workspace<ArrowRight size={15}/></button> : examples.data ? <div className="sf-example-grid">{examples.data.examples.map(sample => <button key={sample.id} onClick={() => onIntake(sample.channel,sample)}><SourceIcon channel={sample.channel}/><strong>{sample.title}</strong><span>Use example <ArrowRight size={14}/></span></button>)}</div> : <p className="sf-muted">{examples.isError ? 'Demo examples are unavailable. You can still add your own source.' : 'Loading demo examples…'}</p>}<p className="sf-fine-print">Synthetic sources use the same checks. Eligible invoices follow the configured payment policy.</p></section>}</div>}
  </main>;
}

type Entry={key:string;file:File;detected:{channel:InboxChannel;reason:string}|null;pending?:boolean;result?:{channel:InboxChannel;id:string};error?:string};
const ACCEPT='.pdf,.txt,.eml,.mp3,.wav,.m4a,.ogg,.webm,.mp4,.aac,.flac,application/pdf,text/plain,message/rfc822,audio/*';
/** Client-side preview of the server's detection; the server's result is authoritative. */
async function previewDetection(file:File):Promise<Entry['detected']>{
 const byFile=detectFromFile({filename:file.name,mimeType:file.type||'application/octet-stream'});if(byFile)return byFile;
 if(/\.pdf$/i.test(file.name)||file.type==='application/pdf')return null;
 if(file.size<=2*1024*1024&&(/\.txt$/i.test(file.name)||file.type.startsWith('text/')))return detectFromText(await file.text());
 return null;
}
export function IntakeDialog({channel,onClose,payables,example,onNotice,onComplete,onBatch}:IntakeDialogProps){
  const [title,setTitle]=useState(''),[sender,setSender]=useState(''),[text,setText]=useState(''),[payableId,setPayableId]=useState(''),[entries,setEntries]=useState<Entry[]>([]),[mode,setMode]=useState<'files'|'text'>('files'),[dragging,setDragging]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');
  const [testInvoiceBusy,setTestInvoiceBusy]=useState(false),[testInvoiceMessage,setTestInvoiceMessage]=useState('');
  const testInvoiceLock=useRef(false),fileInput=useRef<HTMLInputElement>(null),opener=useRef<HTMLElement|null>(null);
  const open=channel!==null;
  useEffect(()=>{setTitle(example?.title||'');setText(example?.text||'');setPayableId(example?.payableId||'');setSender(example?.sender||'');setEntries([]);setMode(example?'text':'files');setError('');setTestInvoiceMessage('');},[open,example]);
  async function saveTestInvoice(){if(testInvoiceLock.current)return;testInvoiceLock.current=true;setTestInvoiceBusy(true);setTestInvoiceMessage('');setError('');try{const filename=await downloadNextTestInvoice();setTestInvoiceMessage(`${filename} is ready. Drop the downloaded PDF here to review it.`);}catch(error){setError(publicText(error instanceof Error?error.message:'The test invoice could not be downloaded.'));}finally{testInvoiceLock.current=false;setTestInvoiceBusy(false);}}
  async function addFiles(list:FileList|File[]|null){
   const files=[...(list??[])].slice(0,20);if(!files.length)return;setError('');
   const tooBig=files.filter(f=>f.size>10*1024*1024);if(tooBig.length)setError(`${tooBig.map(f=>f.name).join(', ')} exceed${tooBig.length===1?'s':''} 10 MiB and ${tooBig.length===1?'was':'were'} not added.`);
   const added=files.filter(f=>f.size<=10*1024*1024).map(file=>({key:`${file.name}-${file.size}-${file.lastModified}-${Math.random()}`,file,detected:null,pending:true}));
   setEntries(current=>[...current,...added]);setMode('files');
   for(const entry of added){const detected=await previewDetection(entry.file).catch(()=>null);setEntries(current=>current.map(e=>e.key===entry.key?{...e,detected,pending:false}:e));}
  }
  const textDetection=text.trim()?detectFromText(text):null;
  const single=mode==='text'?!!text.trim():entries.length===1;
  const invoiceLikely=mode==='text'?textDetection?.channel==='invoice':entries.length===1&&(entries[0]!.detected?.channel==='invoice'||entries[0]!.detected===null);
  const ready=mode==='text'?!!text.trim():entries.some(e=>!e.result);
  async function submit(){
   setBusy(true);setError('');
   try{
    if(mode==='text'){const result=await post<InboxItem|{item:InboxItem}>('/inbox',{title:title.trim()||undefined,sender:sender.trim()||undefined,text:text.trim(),payableId:invoiceLikely?payableId||undefined:undefined});const item='item'in result?result.item:result;onComplete(item.id);onNotice(`Added to your inbox · detected as ${channelNames[item.channel].toLowerCase()}.`);return;}
    let lastId='',done=0,failed=0;const kinds:string[]=[],added:string[]=entries.filter(e=>e.result).map(e=>e.result!.id);
    for(const entry of entries){
     if(entry.result)continue;
     const body=new FormData();if(single&&title.trim())body.append('title',title.trim());if(sender.trim())body.append('sender',sender.trim());if(single&&invoiceLikely&&payableId)body.append('payableId',payableId);body.append('file',entry.file);
     try{const result=await request<InboxItem|{item:InboxItem}>('/inbox',{method:'POST',body});const item='item'in result?result.item:result;lastId=item.id;added.push(item.id);done++;kinds.push(channelNames[item.channel].toLowerCase());setEntries(current=>current.map(e=>e.key===entry.key?{...e,result:{channel:item.channel,id:item.id},error:undefined}:e));}
     catch(e){failed++;const message=publicText(e instanceof Error?e.message:'Upload failed.');setEntries(current=>current.map(x=>x.key===entry.key?{...x,error:message}:x));}
    }
    if(failed){setError(`${failed} file${failed===1?'':'s'} could not be added. The others were added and are being checked.`);if(added.length>1)onBatch?.(added,{keepOpen:true});return;}
    if(added.length>1&&onBatch){onBatch(added);onNotice(`${done} items added · ${[...new Set(kinds)].join(', ')}. Follow them in the batch tracker.`);return;}
    if(lastId){onComplete(lastId);onNotice(done===1?`Added to your inbox · detected as ${kinds[0]}.`:`${done} items added · ${[...new Set(kinds)].join(', ')}. Each is checked separately.`);}
   }catch(e){setError(publicText(e instanceof Error?e.message:'The source could not be added. Please try again.'));}finally{setBusy(false);}
  }
  const label=(entry:Entry)=>entry.result?`${channelNames[entry.result.channel]} · added`:entry.pending?'Detecting…':entry.detected?channelNames[entry.detected.channel]:'Detected on upload';
  return <Dialog.Root open={open} onOpenChange={next=>!next&&!busy&&onClose()}><Dialog.Portal><Dialog.Overlay className="sf-dialog-overlay"/><Dialog.Content className="sf-dialog sf-intake-dialog" onOpenAutoFocus={()=>{opener.current=document.activeElement instanceof HTMLElement?document.activeElement:null;}} onCloseAutoFocus={event=>{event.preventDefault();(opener.current?.isConnected?opener.current:document.querySelector<HTMLElement>('.wf-title-row button'))?.focus({preventScroll:true});}}><div className="sf-dialog-heading"><div><Dialog.Title>Add to inbox</Dialog.Title><Dialog.Description>Drop invoices, emails, voice notes or messages. The type is detected automatically.</Dialog.Description></div><Dialog.Close className="sf-icon-btn" aria-label="Close add to inbox" disabled={busy}><X size={20}/></Dialog.Close></div><form onSubmit={e=>{e.preventDefault();void submit();}}>
    {mode==='files'?<>
     <label className={`sf-drop-zone ${dragging?'is-dragging':''} ${entries.length?'has-files':''}`} onDragOver={e=>{e.preventDefault();if(!busy)setDragging(true);}} onDragLeave={()=>setDragging(false)} onDrop={e=>{e.preventDefault();setDragging(false);if(!busy)void addFiles(e.dataTransfer.files);}}>
      <span className="sf-drop-icon"><Upload size={24}/></span><span className="sf-drop-copy"><strong>{dragging?'Drop to add':'Drop files here or browse'}</strong><small>PDF invoices · .eml emails · audio voice notes · .txt messages — up to 20 files, 10 MiB each</small></span>
      <span className="sf-drop-kinds" aria-hidden="true">{(['invoice','email','voice','text'] as const).map(kind=>{const Icon=sourceIcons[kind];return <span key={kind}><Icon size={15}/>{channelNames[kind]}</span>;})}</span>
      <input ref={fileInput} type="file" multiple accept={ACCEPT} disabled={busy} aria-label="Choose files to add" onChange={e=>{void addFiles(e.target.files);e.currentTarget.value='';}}/>
     </label>
     {entries.length>0&&<ul className="sf-drop-list" aria-label="Files to add">{entries.map(entry=>{const kind=entry.result?.channel??entry.detected?.channel;const Icon=kind?sourceIcons[kind]:FileText;return <li key={entry.key} className={entry.error?'has-error':entry.result?'is-done':''}><span className={`sf-drop-file-icon ${kind?`sf-channel-${kind}`:''}`}><Icon size={17}/></span><div><strong>{entry.file.name}</strong><small>{entry.error??(entry.detected&&!entry.result?entry.detected.reason:entry.result?'Being checked now':`${Math.max(1,Math.round(entry.file.size/1024))} KB`)}</small></div><span className={`sf-detected ${kind?`sf-channel-${kind}`:''}`}>{entry.result?<Check size={13}/>:null}{label(entry)}</span>{!entry.result&&<button type="button" className="sf-icon-btn" aria-label={`Remove ${entry.file.name}`} disabled={busy} onClick={()=>setEntries(current=>current.filter(e=>e.key!==entry.key))}><X size={15}/></button>}</li>;})}</ul>}
     <button type="button" className="sf-text-btn sf-paste-toggle" disabled={busy} onClick={()=>setMode('text')}><MessageSquare size={15}/>Paste text instead</button>
    </>:<>
     <label className="sf-field">Paste a message, invoice, email or transcript<textarea rows={7} maxLength={40000} value={text} disabled={busy} onChange={e=>setText(e.target.value)} placeholder="Paste the complete content. Email headers, invoice fields or a call transcript are recognised automatically…"/></label>
     <div className="sf-paste-meta">{textDetection?<span className={`sf-detected sf-channel-${textDetection.channel}`}>Detected: {channelNames[textDetection.channel]} <small>· {textDetection.reason}</small></span>:<span className="sf-fine-print">The type appears as you paste.</span>}<button type="button" className="sf-text-btn" disabled={busy} onClick={()=>setMode('files')}><Upload size={15}/>Upload files instead</button></div>
    </>}
    <div className="sf-test-invoice-download"><button type="button" className="sf-text-btn" disabled={busy||testInvoiceBusy} aria-busy={testInvoiceBusy} onClick={()=>void saveTestInvoice()}>{testInvoiceBusy?<LoaderCircle className="sf-spin" size={15}/>:<ArrowDownToLine size={15}/>} {testInvoiceBusy?'Preparing test invoice…':'Download next 10 DEMO test invoice'}</button>{testInvoiceMessage&&<p className="sf-fine-print" role="status">{testInvoiceMessage}</p>}</div>
    <details className="sf-form-details"><summary>Optional details<ChevronDown size={15}/></summary>{single&&<label className="sf-field">Title<input value={title} maxLength={160} disabled={busy} onChange={e=>setTitle(e.target.value)} placeholder="A short name for this item"/></label>}<label className="sf-field">Sender or speaker<input value={sender} maxLength={254} disabled={busy} onChange={e=>setSender(e.target.value)} placeholder="Name or address, if known (not verified)"/></label>{single&&invoiceLikely&&<label className="sf-field">Match to a registered invoice<select value={payableId} disabled={busy} onChange={e=>setPayableId(e.target.value)}><option value="">Match using the invoice reference</option>{payables.map(payable=><option key={payable.id} value={payable.id}>{payable.invoiceReference} · {payable.supplierName} · {amount(payable.amountAtomic)} DEMO</option>)}</select><small>Leave this blank to match the reference in the document.</small></label>}</details>
    {error&&<div className="sf-inline-error" role="alert"><AlertTriangle size={17}/><span>{error}</span></div>}<p className="sf-intake-note">The type only routes intake. Security and finance checks run on every item&apos;s content, and nothing is paid without a wallet signature.</p><div className="sf-dialog-actions"><button type="button" className="sf-btn sf-btn-secondary" disabled={busy} onClick={onClose}>Cancel</button><button type="submit" className="sf-btn sf-btn-primary" disabled={busy||!ready||entries.some(e=>e.pending)}>{busy?<LoaderCircle className="sf-spin" size={16}/>:<Plus size={16}/>} {busy?'Adding…':mode==='files'&&entries.filter(e=>!e.result).length>1?`Add ${entries.filter(e=>!e.result).length} items`:'Add & review'}</button></div>
  </form></Dialog.Content></Dialog.Portal></Dialog.Root>;
}

export function InboxDetail(props:InboxDetailProps){
  const Page=props.embedded?'section':'main';
  const client=useQueryClient();const detail=useQuery({queryKey:['inbox-item',props.id],queryFn:()=>request<InboxItem>(`/inbox/${props.id}`),enabled:props.authenticated,refetchInterval:5000});const item=detail.data;
  const [selected,setSelected]=useState('security'),[decision,setDecision]=useState<'approve'|'reject'|'request_information'|null>(null),[note,setNote]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
  const [reportBusy,setReportBusy]=useState(false),[reportError,setReportError]=useState(''),[reportMessage,setReportMessage]=useState('');
  const reportLock=useRef(false);
  const alreadyPaid=item?.payment?.settlementStatus==='SETTLED'||item?.reviewBlock?.code==='INVOICE_ALREADY_SETTLED';
  useEffect(()=>{if(alreadyPaid&&(decision==='approve'||decision==='request_information'&&item?.status!=='quarantined'))setDecision(null);},[alreadyPaid,decision,item?.status]);
  async function saveReport(){if(!item||reportLock.current)return;reportLock.current=true;setReportBusy(true);setReportError('');setReportMessage('');try{await downloadPdfReport(`/inbox/${item.id}/report.pdf`,`review-report-${item.title}.pdf`);setReportMessage('Your PDF download has started.');}catch(error){setReportError(error instanceof Error?error.message:'The report could not be downloaded. Please try again.');}finally{reportLock.current=false;setReportBusy(false);}}
  const stage=item?.stages.find(s=>s.id===selected)||item?.stages[0];const reviewer=async()=>{if(!item||!decision||alreadyPaid&&(decision==='approve'||decision==='request_information'&&item.status!=='quarantined'))return;setBusy(true);setError('');try{await post(`/inbox/${item.id}/review`,{expectedVersion:item.version,decision,note});setDecision(null);setNote('');await Promise.all([client.invalidateQueries({queryKey:['inbox-item',item.id]}),client.invalidateQueries({queryKey:['inbox']}),client.invalidateQueries({queryKey:['inbox-notifications']})]);props.onNotice('Your review decision was recorded. Payment execution follows the approved policy.');}catch(e){setError(e instanceof Error?e.message:'Unable to record the review.');}finally{setBusy(false)}};
  if(!props.authenticated)return <Page className="sf-page"><div className="sf-state-card"><LockKeyhole size={28}/><h2>Sign in to open this item</h2><p>Source content and review history belong to your private workspace.</p><button className="sf-btn sf-btn-primary" onClick={props.onLogin}>Sign in</button></div></Page>;
  if(detail.isError)return <Page className="sf-page"><ErrorState error={detail.error} retry={()=>void detail.refetch()}/></Page>;
  if(!item)return <Page className="sf-page"><div className="sf-state-card"><LoaderCircle className="sf-spin" size={25}/><p>Opening your review…</p></div></Page>;
  const highRisk=item.risks.some(r=>r.severity==='high');
  const completedChecks=item.stages.filter(check=>['passed','not_applicable'].includes(check.status)).length;
  return <Page className="sf-page sf-detail-page sf-detail-compact" data-embedded={props.embedded||undefined}>
    {!props.embedded&&<button className="sf-back-link" onClick={()=>props.navigate('/')}><ArrowLeft size={15}/>Back to inbox</button>}
    {!props.embedded?<div className="sf-detail-heading"><SourceIcon channel={item.channel}/><div><div className="sf-detail-meta">{channelNames[item.channel]}<span>·</span>{time(item.createdAt)}</div><h1>{item.title}</h1><p>{item.sender||'Manually imported source'}</p></div><StatusPill status={item.status}/></div>:<div className="sf-detail-meta"><span>{channelNames[item.channel]}</span><span>·</span><span>{time(item.createdAt)}</span><span>·</span><span>{item.sender||'Manually imported source'}</span><StatusPill status={item.status}/></div>}
    <div className={`sf-decision-banner sf-decision-${alreadyPaid&&item.status!=='quarantined'?'approved':item.status}`}><span>{item.status==='quarantined'?<ShieldAlert size={24}/>:item.status==='approved'||alreadyPaid?<CheckCheck size={24}/>:<UserRound size={24}/>}</span><div><strong>{item.status==='quarantined'?'Security hold':alreadyPaid?'Already paid':item.status==='approved'?'Workflow review complete':item.status==='rejected'?'Request rejected':item.status==='processing'?'Checking this source':'Your review is needed'}</strong><p>{publicText(alreadyPaid&&item.status!=='quarantined'?(item.reviewBlock?.message||'This invoice already has a verified payment. It cannot be paid again. Upload a different invoice to run another test.'):(item.approval?.reason||'Review the source and findings before deciding.'))}</p>{alreadyPaid&&item.status==='quarantined'&&<p>This invoice is already paid. The security findings still need your attention.</p>}</div></div>
    <div className={`sf-detail-overview ${item.payment&&!props.paymentEmbedded?'has-payment':''}`}>
      <section className="sf-card sf-action-card"><h2>{alreadyPaid?'Payment record':['needs_review','quarantined'].includes(item.status)?'Review decision':'Next step'}</h2><p>{alreadyPaid?'View the recorded payment or download this review. No additional payment is needed.':item.status==='approved'?(props.paymentEmbedded?'Review the payment below for its current authorization and outcome.':!item.payment?'The checks are complete. No external action was taken.':item.payment.requiresWalletSignature===false?'Workflow checks are complete. Payment follows your registered policy; its outcome is shown separately.':'Workflow checks are complete. Payment still needs separate authorization.'):item.status==='rejected'?'The source and decision are saved in your history.':item.status==='processing'?'Checks update automatically as they complete.':'Check the findings and original source before recording a decision.'}</p>
        {item.status==='quarantined'&&<p className="sf-quarantine-note">This source cannot be approved while the security hold is active. Confirm the request through a trusted contact, then submit a corrected source.</p>}
        <div className="sf-review-actions">{item.linkedCaseId&&(alreadyPaid||item.payment?.requiresWalletSignature!==false)&&<button className="sf-btn sf-btn-primary" onClick={()=>props.navigate(`/cases/${item.linkedCaseId}`)}>{alreadyPaid?'View payment receipt':'Open payment review'}<ArrowUpRight size={16}/></button>}{['needs_review','quarantined'].includes(item.status)&&<>{item.status!=='quarantined'&&!alreadyPaid&&<button className="sf-btn sf-btn-primary" onClick={()=>{setDecision('approve');setError('');}}><Check size={16}/>Approve workflow</button>}{(!alreadyPaid||item.status==='quarantined')&&<button className="sf-btn sf-btn-secondary" onClick={()=>{setDecision('request_information');setError('');}}>Request information</button>}<button className="sf-btn sf-btn-danger" onClick={()=>{setDecision('reject');setError('');}}>{alreadyPaid&&item.status==='needs_review'?'Dismiss duplicate':'Reject request'}</button></>}<button className="sf-btn sf-btn-secondary" disabled={reportBusy} aria-busy={reportBusy} onClick={()=>void saveReport()}>{reportBusy?<LoaderCircle className="sf-spin" size={16}/>:<ArrowDownToLine size={16}/>} {reportBusy?'Preparing PDF…':'Download PDF report'}</button></div>
        {reportError&&<div className="sf-inline-error" role="alert"><AlertTriangle size={17}/><span>We couldn’t download your report. {reportError}<br/><button className="sf-text-btn" disabled={reportBusy} onClick={()=>void saveReport()}>Try again</button></span></div>}{reportMessage&&<p className="sf-fine-print" role="status">{reportMessage}</p>}
        {!alreadyPaid&&item.payment?.requiresWalletSignature!==false&&['needs_review','quarantined'].includes(item.status)&&<p className="sf-compact-note">Workflow approval does not authorize a payment.</p>}
      </section>
      {item.payment&&!props.paymentEmbedded&&<section className="sf-card sf-payment-summary"><h2>Payment status</h2><span className="sf-pill">{item.payment.settlementStatus==='SETTLED'?'Receipt verified':item.payment.executionStatus==='UNKNOWN'?'Outcome unknown':item.payment.executionStatus==='HELD'?'Payment paused':'Not confirmed'}</span><p>{item.payment.settlementStatus==='SETTLED'?'A payment receipt has been verified.':item.payment.executionStatus==='UNKNOWN'?'Reconcile this payment before trying again.':item.payment.executionStatus==='HELD'?'Review the findings before proceeding.':'No verified settlement is recorded for this source.'}</p><small>{item.payment.requiresWalletSignature===false?'Registered payment policy':'Separate payment approval required'}</small>{item.payment.txHash&&<details className="sf-receipt-details"><summary>View receipt details<ChevronDown size={13}/></summary><p>{item.payment.authorityModel||'Registered payment authority'}</p><code>{item.payment.txHash}</code></details>}</section>}
    </div>
    {item.risks.length>0&&<section className="sf-card sf-risk-panel"><div className="sf-section-heading"><h2>Security findings</h2><span className="sf-count-bubble">{item.risks.length}</span></div>{item.risks.map(risk=><article className={`sf-risk-item sf-risk-${risk.severity}`} key={risk.code}><span className="sf-risk-symbol"><ShieldAlert size={19}/></span><div><div><h3>{risk.title}</h3><span>{risk.severity==='high'?'High priority':risk.severity==='medium'?'Needs review':'Information'}</span></div><p>{publicText(risk.detail)}</p>{Array.isArray(risk.evidence)&&risk.evidence.length>0&&<details className="sf-inline-disclosure"><summary>View evidence<ChevronDown size={14}/></summary><Evidence value={risk.evidence}/></details>}</div></article>)}</section>}
    <details className="sf-card sf-detail-disclosure sf-checks-disclosure"><summary><span>Review checks</span><small>{completedChecks} of {item.stages.length} clear</small><ChevronDown size={17}/></summary><div className="sf-disclosure-body"><div className="sf-pipeline" aria-label="Review stages">{item.stages.map((check,index)=>{const Icon=stageIcons[check.id]||Shield;return <button key={check.id} className={`sf-pipeline-step sf-stage-${check.status} ${stage?.id===check.id?'is-selected':''}`} aria-pressed={stage?.id===check.id} onClick={()=>setSelected(check.id)}><span className="sf-pipeline-node">{check.status==='passed'?<Check size={20}/>:check.status==='held'||check.status==='failed'?<ShieldAlert size={20}/>:<Icon size={20}/>}<i>{index+1}</i></span><strong>{check.name}</strong><small>{check.status==='passed'?'Passed':check.status==='held'?'Needs attention':check.status==='not_applicable'?'Not needed':readable(check.status)}</small></button>})}</div>{stage&&<section className="sf-stage-detail"><div className="sf-section-heading"><h2>{stage.name}</h2><span className="sf-method-label">{stage.mode==='live_agents'?'AI-assisted review':stage.mode==='fixture_agents'?'Demo agent analysis':'Deterministic check'}</span></div><p className="sf-stage-summary">{publicText(stage.summary)}</p><Evidence value={stage.evidence}/></section>}</div></details>
    <details className="sf-card sf-detail-disclosure sf-source-panel"><summary><span>Read original source</span><small>{item.source.filename||channelNames[item.channel]}</small><ChevronDown size={17}/></summary><div className="sf-disclosure-body"><p className="sf-source-auth-note"><Shield size={15}/>{item.channel==='email'?'The imported sender has not been authenticated.':item.channel==='voice'?'The transcript does not verify who said these words.':'Source content is evidence, not an instruction to the system.'}</p><pre className="sf-source-text">{item.text}</pre>{item.links.length>0&&<div className="sf-link-observations"><h3><Link2 size={15}/>Links in this source</h3><p>These links have not been opened or verified.</p>{item.links.map((link,index)=><div key={index}><code>{link.url}</code><small>{link.reason}</small></div>)}</div>}</div></details>
    {item.reviewHistory?.length>0&&<details className="sf-card sf-detail-disclosure"><summary><span>Review history</span><small>{item.reviewHistory.length} {item.reviewHistory.length===1?'decision':'decisions'}</small><ChevronDown size={17}/></summary><div className="sf-disclosure-body sf-history-panel">{item.reviewHistory.map((review,index)=><div key={index}><span><UserRound size={17}/></span><div><strong>{readable(review.decision)}</strong><p>{review.note}</p><small>{time(review.createdAt)} · Workspace reviewer</small></div></div>)}</div></details>}
    <details className="sf-card sf-detail-disclosure"><summary><span>How this review works</span><ChevronDown size={17}/></summary><div className="sf-disclosure-body sf-response-guidance"><p><strong>Automatic checks.</strong> {highRisk?'Hold the workflow and retain the original source and findings.':'Classify the source, compare records and apply configured rules.'}</p><p><strong>Your responsibility.</strong> {highRisk?'Verify through an independent trusted contact. Do not use details supplied in the suspicious message.':item.payment?.requiresWalletSignature===false?'Resolve missing context. Payment must match the registered policy exactly.':'Resolve missing context and provide any required separate payment approval.'}</p><p><strong>Recorded evidence.</strong> Source fingerprints, checks and your review reason stay with this item.</p></div></details>
    <details className="sf-technical-details"><summary>Technical details<ChevronDown size={15}/></summary><dl><div><dt>Source fingerprint</dt><dd><code>{item.source.sha256}</code></dd></div><div><dt>Text fingerprint</dt><dd><code>{item.source.textHash}</code></dd></div><div><dt>Item version</dt><dd>{item.version}</dd></div><div><dt>Extraction method</dt><dd>{readable(item.source.extraction)}</dd></div>{item.payment?.txHash&&<div><dt>Transaction reference</dt><dd><code>{item.payment.txHash}</code></dd></div>}</dl></details>
    <Dialog.Root open={decision!==null} onOpenChange={open=>!open&&!busy&&setDecision(null)}><Dialog.Portal><Dialog.Overlay className="sf-dialog-overlay"/><Dialog.Content className="sf-dialog sf-review-dialog"><div className="sf-dialog-heading"><div><Dialog.Title>{decision==='approve'?'Approve this workflow?':decision==='reject'?(alreadyPaid&&item.status==='needs_review'?'Dismiss this duplicate?':'Reject this request?'):'Request information'}</Dialog.Title><Dialog.Description>{decision==='approve'?'Record your reason. Payment follows its separate approval policy.':decision==='reject'?(alreadyPaid&&item.status==='needs_review'?'Close this duplicate review. The original payment and both records stay in your history.':'The item and your reason will remain in the history.'):'Record what is missing. This does not send a message to the sender.'}</Dialog.Description></div><Dialog.Close className="sf-icon-btn" aria-label="Close review decision" disabled={busy}><X size={19}/></Dialog.Close></div><label className="sf-field">Reason for your decision<textarea rows={4} value={note} maxLength={1000} onChange={e=>setNote(e.target.value)} placeholder="What did you check, or what is missing?"/><small>At least 5 characters. Saved with this review.</small></label>{error&&<p className="sf-inline-error" role="alert">{error}</p>}<div className="sf-dialog-actions"><button className="sf-btn sf-btn-secondary" onClick={()=>setDecision(null)} disabled={busy}>Cancel</button><button className="sf-btn sf-btn-primary" disabled={busy||note.trim().length<5} onClick={()=>void reviewer()}>{busy&&<LoaderCircle className="sf-spin" size={15}/>}Record decision<ArrowRight size={15}/></button></div></Dialog.Content></Dialog.Portal></Dialog.Root>
  </Page>;
}

export function Notifications(props:NotificationsProps){const Page=props.embedded?'section':'main';const client=useQueryClient();const notifications=useQuery({queryKey:['inbox-notifications'],queryFn:()=>request<{notifications:InboxNotification[]}>('/inbox/notifications'),enabled:props.authenticated,refetchInterval:10000});const [busy,setBusy]=useState<string|null>(null);const items=notifications.data?.notifications||[];async function mark(notification:InboxNotification){setBusy(notification.id);try{await post(`/inbox/notifications/${notification.id}/read`);await client.invalidateQueries({queryKey:['inbox-notifications']});}catch(e){props.onNotice(e instanceof Error?e.message:'Could not update notification');}finally{setBusy(null)}}return <Page className="sf-page" data-embedded={props.embedded||undefined}>{!props.embedded&&<PageHeading eyebrow="NOTHING IMPORTANT GETS LOST" title="Your activity" description="Security holds, review requests and recorded decisions, all in one place."/>}<section className="sf-card sf-activity-list">{!props.authenticated?<div className="sf-state-card"><Bell size={29}/><h2>Your workspace updates live here</h2><p>Sign in to see the events that need your attention.</p><button className="sf-btn sf-btn-primary" onClick={props.onLogin}>Sign in</button></div>:notifications.isError?<ErrorState error={notifications.error} retry={()=>void notifications.refetch()}/>:notifications.isLoading?<div className="sf-state-card"><LoaderCircle className="sf-spin" size={25}/><p>Loading activity…</p></div>:items.length?items.map(n=><article key={n.id} className={!n.read?'is-unread':''}><span className={`sf-activity-icon ${['security_hold','payment_attention'].includes(n.kind)?'is-warning':''}`}>{['security_hold','payment_attention'].includes(n.kind)?<ShieldAlert size={21}/>:['workflow_approved','payment_confirmed'].includes(n.kind)?<CheckCheck size={21}/>:<Bell size={21}/>}</span><div><h3>{n.title}{!n.read&&<span className="sf-unread-dot"/>}</h3><p>{n.message}</p><time>{time(n.createdAt)}</time><button className="sf-text-btn" onClick={()=>props.navigate(`/inbox/${n.itemId}`)}>Open item<ArrowRight size={14}/></button></div>{!n.read&&<button className="sf-btn sf-btn-secondary" disabled={busy===n.id} onClick={()=>void mark(n)}>Mark read</button>}</article>):<div className="sf-state-card"><span className="sf-state-icon"><Bell size={29}/></span><h2>You're all caught up</h2><p>Updates will appear when an item is reviewed or needs your attention.</p></div>}</section></Page>}

type ConnectionState = {internal: {configured: boolean; url: string; authentication: 'HMAC-SHA256'; scope: string}; gmail: {configured: boolean}; outlook: {configured: boolean}; voice: {configured: boolean}};
function Connections(props: InboxPagesProps & {onIntake: (channel: InboxChannel) => void}) {
  const connections = useQuery({queryKey: ['inbox-connections'], queryFn: () => request<ConnectionState>('/inbox/connections'), enabled: props.authenticated, retry: false});
  const status = (configured?: boolean) => !props.authenticated ? 'Sign in to check' : connections.isError ? 'Status unavailable' : configured === undefined ? 'Checking setup…' : configured ? 'Configured' : 'Not configured';
  const sources = [
    {name: 'Invoice documents', channel: 'invoice' as const, description: 'Upload a text-based PDF or text file and match it with a registered invoice.', action: 'Import invoice', tag: 'Manual import available'},
    {name: 'Email messages', channel: 'email' as const, description: 'Paste an email or upload an .eml file with its subject, sender and body.', action: 'Import an email', tag: 'Manual import available'},
    {name: 'Voice requests', channel: 'voice' as const, description: 'Paste a transcript or upload audio. Automatic transcription needs a configured provider.', action: 'Add a transcript', tag: connections.data?.voice.configured ? 'Transcription configured' : 'Transcript import available'},
    {name: 'Text & client requests', channel: 'text' as const, description: 'Bring a message or request into the inbox for classification and review.', action: 'Add a request', tag: 'Manual import available'}
  ];
  return <main className="sf-page">
    <PageHeading eyebrow="BRING THE CONTEXT TOGETHER" title="Your sources" description="Start with manual imports. Integration status is checked against your workspace configuration."/>
    <section className="sf-connections-intro"><span><Workflow size={26}/></span><div><h2>One review path, wherever work begins</h2><p>Invoices, messages and transcripts use the same recorded security and policy checks. Imported sender names and speaker identities remain unverified.</p></div></section>
    {connections.isError && <div className="sf-connection-error" role="alert"><AlertTriangle size={18}/><span>We couldn't check integration settings. Manual imports remain available when the workspace is reachable.</span><button className="sf-btn sf-btn-secondary" onClick={() => void connections.refetch()}><RefreshCw size={14}/>Retry</button></div>}
    <div className="sf-connections-grid">{sources.map(source => <section className="sf-card sf-connection-card" key={source.channel}><SourceIcon channel={source.channel}/><h2>{source.name}</h2><p>{source.description}</p><span className="sf-connection-status"><i/>{source.tag}</span><button className="sf-btn sf-btn-secondary" onClick={() => props.onIntake(source.channel)}>{source.action}<ArrowRight size={15}/></button></section>)}</div>
    <section className="sf-card sf-integration-card"><div><span className="sf-label">MAILBOX CONNECTIONS</span><h2>A connected mailbox needs a real setup</h2><p>Manual email import works now. Automatic mailbox synchronization requires an OAuth integration and account consent; no connector is enabled by clicking an import button.</p></div><div className="sf-provider-status"><span><Mail size={20}/><strong>Gmail</strong><small>{status(connections.data?.gmail.configured)}</small></span><span><Mail size={20}/><strong>Microsoft Outlook</strong><small>{status(connections.data?.outlook.configured)}</small></span></div></section>
    <section className="sf-card sf-integration-card sf-internal-integration"><div><span className="sf-label">INTERNAL SYSTEMS</span><h2>Bring requests from your own tools</h2><p>A signed webhook can receive invoice and message sources from an internal system. It only adds items to the review pipeline; it cannot authorize a payment.</p><span className={`sf-connection-status ${connections.data?.internal.configured ? 'sf-configured' : ''}`}><i/>{status(connections.data?.internal.configured)}</span></div><details className="sf-api-details"><summary>View integration details<ChevronDown size={15}/></summary>{connections.data?.internal && <><code>POST {connections.data.internal.url}</code><p>Authentication: {connections.data.internal.authentication}. Scope: {connections.data.internal.scope}.</p></>}<p>An administrator must configure INBOX_WEBHOOK_SECRET and the intended tenant on the server, then sign each incoming request. The secret is never displayed in this application. Gmail and Outlook still require their own separate connectors.</p></details></section>
    <section className="sf-card sf-integration-card"><div><span className="sf-label">WORKSPACE API</span><h2>Use the same checks everywhere</h2><p>Authorized applications can also submit sources using a workspace session and anti-forgery protection.</p></div><details className="sf-api-details"><summary>View session API details<ChevronDown size={15}/></summary><code>POST /api/v1/inbox</code><p>JSON fields: channel, title, sender, text and optional payableId. Multipart uploads use file plus source metadata. Use the session’s CSRF token and a unique Idempotency-Key. This endpoint creates review items; it does not grant payment authority.</p></details></section>
  </main>;
}
